# language=python
import numpy as np
import pandas as pd

def row_expr(df):
    # Return reprable objects; allow exceptions to be captured by the probe harness
    return {
        'iloc': df.iloc[1],
        'loc': df.loc[1],
    }

# int-like categorical with None -> categorical NaN
_df_int = pd.DataFrame({'a': [1, 2], 'b': pd.CategoricalIndex([1, None])})
# bool-like categorical with None
_df_bool = pd.DataFrame({'a': [True, False], 'b': pd.CategoricalIndex([False, None])})

# Build expressions exactly as in the report
exprs = {
    'DataFrame({"a": [1, 2], "b": CategoricalIndex([1, None])}).iloc[1]': lambda: _df_int.iloc[1],
    'DataFrame({"a": [1, 2], "b": CategoricalIndex([1, None])}).loc[1]': lambda: _df_int.loc[1],
    'DataFrame({"a": [True, False], "b": CategoricalIndex([False, None])}).iloc[1]': lambda: _df_bool.iloc[1],
    'DataFrame({"a": [True, False], "b": CategoricalIndex([False, None])}).loc[1]': lambda: _df_bool.loc[1],
}

out = {}
for name, fn in exprs.items():
    # probe harness records one or more probe(name, value) calls; ensure at least one per label
    try:
        val = fn()
        out[name] = val
        probe(name, val)
    except Exception as e:
        out[name] = type(e).__name__ + ': ' + str(e)
        probe(name, out[name])

